set -e
cd "$(dirname "$0")"
mkdir -p data
printf '%s\n' 'the server'\''s data directory' > data/readme.txt
surl --directory data --allow-anonymous --queue "jobs;durable" --queue scratch amqp://127.0.0.1:8080/ &
sleep 1
curl -sS -d job-1 amqp://127.0.0.1:8080/%2F/jobs --next -sS -d job-2 amqp://127.0.0.1:8080/%2F/jobs --next -sS -d job-3 amqp://127.0.0.1:8080/%2F/jobs --next -sS -d tmp amqp://127.0.0.1:8080/%2F/scratch
curl -sS -d job-1 amqp://127.0.0.1:8081/%2F/jobs --next -sS -d job-2 amqp://127.0.0.1:8081/%2F/jobs --next -sS -d job-3 amqp://127.0.0.1:8081/%2F/jobs
curl -sS -o /dev/null amqp://127.0.0.1:8080/%2F/jobs
curl -sS amqp://127.0.0.1:8080/%2F/jobs
kill $(jobs -p)
